actions.script:
def dashDate = ec.web.parameters.dashDate
def dashDateTo = ec.web.parameters.dashDateTo
def orgId = ec.service.sync().name('zenith.tax.TaxAccessServices.get#AuthorizedActiveOrganization').call().activeOrgId
def tLines=ec.service.sync().name('zenith.tax.TaxServices.get#DashboardTaxLines').call().taxLines ?: []
def zone = ec.user.timeZone.toZoneId()
if (!dashDate) dashDate = dashDateTo ?: ec.user.nowTimestamp.toInstant().atZone(zone).toLocalDate().toString()
if (!dashDateTo) dashDateTo = dashDate
try {
    def from=java.time.LocalDate.parse(dashDate), to=java.time.LocalDate.parse(dashDateTo)
    if(from.year < 1900 || to.year > 9998 || to.isBefore(from) || java.time.temporal.ChronoUnit.DAYS.between(from,to) > 366) throw new IllegalArgumentException()
} catch(Exception ignored) {
    ec.web.response.setStatus(400)
    ec.web.sendTextResponse('Select valid ordered dates spanning at most one year.','text/plain',null); return
}
def ps = java.sql.Timestamp.from(java.time.LocalDate.parse(dashDate).atStartOfDay(zone).toInstant())
def pe = java.sql.Timestamp.from(java.time.LocalDate.parse(dashDateTo).plusDays(1).atStartOfDay(zone).toInstant())
def lines = (ps && pe) ? tLines.findAll { it.documentDate != null && !it.documentDate.before(ps) && it.documentDate.before(pe) } : tLines
def df = new java.text.SimpleDateFormat("yyyy-MM-dd"); df.setTimeZone(ec.user.timeZone)
def esc = { v -> def s = (v == null) ? '' : v.toString(); if (v instanceof CharSequence && s ==~ /(?s)^[=+@\-\t\r].*/) s = "'" + s; (s.contains(',') || s.contains('"') || s.contains("\n")) ? ('"' + s.replace('"','""') + '"') : s }
def sb = new StringBuilder("ID,Ref Type,Ref ID,Tax,Rate,Taxable Amount,Tax Amount,Currency,Date\n")
lines.each { sb.append([esc(it.taxLineDetailId), esc(it.referenceType), esc(it.referenceId), esc(it.taxName), esc(it.taxRate), esc(it.taxableAmount), esc(it.taxAmount), esc(it.currencyUomId ?: 'INR'), esc(it.documentDate != null ? df.format(it.documentDate) : '')].join(',')).append("\n") }
ec.web.sendTextResponse(sb.toString(), "text/csv", "TaxLines.csv")

import java.math.BigDecimal
import java.math.RoundingMode
def _uri = (ec.web?.request?.requestURI ?: ''); def _zi = _uri.indexOf('/zenith/'); appBase = _zi > 0 ? _uri.substring(0, _zi) : ''
def zone = ec.user.timeZone.toZoneId()
def pretty = java.time.format.DateTimeFormatter.ofPattern("dd MMM yyyy", ec.user.locale)
def now = ec.user.nowTimestamp
def todayStr = now.toInstant().atZone(zone).toLocalDate().toString()

def orgId = ec.service.sync().name('zenith.tax.TaxAccessServices.get#AuthorizedActiveOrganization').call().activeOrgId
def tLines=ec.service.sync().name('zenith.tax.TaxServices.get#DashboardTaxLines').call().taxLines ?: []

if (!dashDate) dashDate = dashDateTo ?: todayStr
if (!dashDateTo) dashDateTo = dashDate
try {
    def from=java.time.LocalDate.parse(dashDate), to=java.time.LocalDate.parse(dashDateTo)
    if(from.year < 1900 || to.year > 9998 || to.isBefore(from) || java.time.temporal.ChronoUnit.DAYS.between(from,to) > 366) throw new IllegalArgumentException()
} catch(Exception ignored) {
    ec.web.response.setStatus(400)
    ec.web.sendTextResponse('Select valid ordered dates spanning at most one year.','text/plain',null); return
}

def first = java.time.LocalDate.parse(dashDate), last = java.time.LocalDate.parse(dashDateTo)
def periodStart = java.sql.Timestamp.from(first.atStartOfDay(zone).toInstant())
def periodEndExcl = java.sql.Timestamp.from(last.plusDays(1).atStartOfDay(zone).toInstant())
def priorStart = java.sql.Timestamp.from(first.minusDays(java.time.temporal.ChronoUnit.DAYS.between(first,last) + 1).atStartOfDay(zone).toInstant())
rangeLabel = first == last ? first.format(pretty) : first.format(pretty) + " - " + last.format(pretty)

def inRange = { ts, a, b -> ts != null && !ts.before(a) && ts.before(b) }
def periodLines = tLines.findAll { inRange(it.documentDate, periodStart, periodEndExcl) }
def priorLines  = tLines.findAll { inRange(it.documentDate, priorStart, periodStart) }

BigDecimal totBd = 0G; periodLines.each { totBd += (it.taxAmount ?: 0G) }
BigDecimal priorBd = 0G; priorLines.each { priorBd += (it.taxAmount ?: 0G) }
totalTaxFmt = "₹" + totBd.setScale(2, RoundingMode.HALF_UP).toPlainString()
if (priorBd == 0G) { trendPct = null } else { trendPct = ((totBd - priorBd) * 100G / priorBd).setScale(1, RoundingMode.HALF_UP) }
trendUp = (trendPct != null && trendPct >= 0G)
trendStr = (trendPct == null) ? "—" : ((trendUp ? "+" : "") + trendPct.toPlainString() + "%")

// by type (parse the taxName prefix: SGST@9% / CGST@9% / IGST@18%)
BigDecimal sg = 0G, cg = 0G, ig = 0G, ot = 0G
periodLines.each { def n = (it.taxName ?: '').toString().toUpperCase().trim(); def a = (it.taxAmount ?: 0G)
    if (n.startsWith('SGST') || n.startsWith('UTGST')) sg += a
    else if (n.startsWith('CGST')) cg += a
    else if (n.startsWith('IGST')) ig += a
    else ot += a }
BigDecimal byTot = sg + cg + ig + ot
byTypeTotalFmt = "₹" + byTot.setScale(2, RoundingMode.HALF_UP).toPlainString()
def _pc = { v -> (byTot == 0G) ? "0" : ((v * 100G / byTot).setScale(1, RoundingMode.HALF_UP).toPlainString()) }
sgstFmt = "₹" + sg.setScale(2, RoundingMode.HALF_UP).toPlainString(); sgstPct = _pc(sg)
cgstFmt = "₹" + cg.setScale(2, RoundingMode.HALF_UP).toPlainString(); cgstPct = _pc(cg)
igstFmt = "₹" + ig.setScale(2, RoundingMode.HALF_UP).toPlainString(); igstPct = _pc(ig)
byTypeSeries = "[" + sg.setScale(2,RoundingMode.HALF_UP).toPlainString() + "," + cg.setScale(2,RoundingMode.HALF_UP).toPlainString() + "," + ig.setScale(2,RoundingMode.HALF_UP).toPlainString() + "," + ot.setScale(2,RoundingMode.HALF_UP).toPlainString() + "]"
byTypeHasData = (byTot > 0G)

// daily series across the selected range
def dayMap = [:]
periodLines.each { def day = java.time.Instant.ofEpochMilli(it.documentDate.time).atZone(zone).toLocalDate(); dayMap[day] = ((dayMap[day] ?: 0G)) + (it.taxAmount ?: 0G) }
def labels = []; def vals = []
def dayLabel = java.time.format.DateTimeFormatter.ofPattern("dd MMM", ec.user.locale)
for (def day = first; !day.isAfter(last); day = day.plusDays(1)) {
    labels.add(day.format(dayLabel))
    vals.add(((dayMap[day] ?: 0G) as BigDecimal).setScale(2, RoundingMode.HALF_UP).toPlainString())
}
liabLabelsJson = groovy.json.JsonOutput.toJson(labels)
liabValsJson = "[" + vals.join(",") + "]"
liabHasData = (periodLines.size() > 0)

// recent tax lines for the table (within range; fall back to latest tenant lines if the range is empty)
def tableSrc = periodLines
recentTaxLines = tableSrc.take(8)

// ===== Recent Activities (real, from the most-recently-updated tax records) =====
def _ago = { ts -> if (!ts) return ''; long ms = now.getTime() - ts.getTime(); if (ms < 0) ms = 0
    long mins = (long)(ms/60000L); if (mins < 1) return 'just now'; if (mins < 60) return mins + ' min' + (mins==1?'':'s') + ' ago'
    long hrs = (long)(mins/60L); if (hrs < 24) return hrs + ' hour' + (hrs==1?'':'s') + ' ago'
    long days = (long)(hrs/24L); if (days < 30) return days + ' day' + (days==1?'':'s') + ' ago'
    return (long)(days/30L) + ' month' + ((long)(days/30L)==1?'':'s') + ' ago' }
def _safe = { v, k -> try { return v?.get(k) } catch (Exception e) { return null } }
def acts = []
try { def rl = ec.entity.find("zenith.erp.india.IndiaGstSlab").orderBy("-lastUpdatedStamp").limit(1).list()
    if (rl) { def r = rl[0]; def nm = (_safe(r,'slabName') ?: _safe(r,'gstSlabId') ?: 'Tax rate'); def rt = (_safe(r,'gstRate') ?: _safe(r,'totalRate'))
        acts.add([icon:'receipt_long', color:'green', title:'Tax Rate Updated', sub:(nm.toString() + ((rt != null) ? (' - ' + rt + '%') : '')), ts:r.lastUpdatedStamp]) } } catch (Exception e) {}
try { def q = ec.entity.find("zenith.erp.tax.TaxExemption"); q.condition("organizationPartyId", orgId ?: '_NA_')
    def rl = q.orderBy("-lastUpdatedStamp").limit(1).list()
    if (rl) { def r = rl[0]; acts.add([icon:'description', color:'red', title:'Tax Exemption Updated', sub:(_safe(r,'exemptionNumber') ?: _safe(r,'description') ?: _safe(r,'exemptionId') ?: 'Exemption'), ts:r.lastUpdatedStamp]) } } catch (Exception e) {}
try { def q = ec.entity.find("zenith.erp.tax.TaxRegistration"); q.condition("organizationPartyId", orgId ?: '_NA_')
    def rl = q.orderBy("-lastUpdatedStamp").limit(1).list()
    if (rl) { def r = rl[0]; acts.add([icon:'verified', color:'blue', title:'GST Registration Updated', sub:(_safe(r,'registrationNumber') ?: _safe(r,'registrationId') ?: 'Registration'), ts:r.lastUpdatedStamp]) } } catch (Exception e) {}
acts = acts.findAll { it.ts != null }.sort { -it.ts.getTime() }
activities = acts.collect { [icon:it.icon, color:it.color, title:it.title, sub:(it.sub != null ? it.sub.toString() : ''), time:_ago(it.ts)] }
